1	import React from 'react';
2	import { motion } from 'framer-motion';
3	import clsx from 'clsx';
4	import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
5	import { useExternalScrollThumb } from '@/hooks/use-external-scroll-thumb';
6	import { LINE_TYPES, type LineTypeId, type LineTypeVisibility } from './gcodeLineTypes';
7	import type { ColorByMode, ColorByRange, ContinuousColorByMode } from './gcodeLayer';
8	import { COLOR_BY_LABELS, COLOR_BY_UNITS, COLORMAP_STOPS_HEX, defaultColorByScope, type ColorByScope } from './gcodeColormap';
9	import type { GCodeFileInfo } from '@/hooks/use-gcode-preview';
10	import styles from './GCodeLineTypeLegend.module.scss';
11	
12	interface GCodeLineTypeLegendProps {
13	  /** G-code chargé (statistiques par type de ligne), ou null : toutes les valeurs en « — ». */
14	  fileInfo: GCodeFileInfo | null;
15	  visibility: LineTypeVisibility;
16	  onToggle: (id: LineTypeId, visible: boolean) => void;
17	  /** Critère de coloration actif du tracé (cf. gcodeColormap.ts). */
18	  colorBy: ColorByMode;
19	  setColorBy: (mode: ColorByMode) => void;
20	  /** Portée affichée (curseurs + écrêtage) du mode continu actif, ou null en mode `lineType`. */
21	  activeColorByScope: ColorByScope | null;
22	  setColorByScope: (mode: ContinuousColorByMode, scope: ColorByScope) => void;
23	  /** Bornes (mm) et valeur active du curseur « Précision du rendu », ou null hors mode continu. */
24	  renderPrecisionBounds: { min: number; max: number } | null;
25	  activeRenderPrecisionMm: number | null;
26	  setRenderPrecision: (mode: ContinuousColorByMode, mm: number | null) => void;
27	}
28	
29	const DASH = '—';
30	
31	const formatNumber = (value: number, digits: number) => value.toFixed(digits).replace('.', ',');
32	
33	/** « 8 m 45 s », « 12 s » ; heures sans secondes (« 1 h 12 m ») pour tenir dans la colonne. */
34	const formatDuration = (seconds: number) => {
35	  const total = Math.round(seconds);
36	  if (total === 0) return '< 1 s';
37	  const h = Math.floor(total / 3600);
38	  const m = Math.floor((total % 3600) / 60);
39	  const s = total % 60;
40	  if (h > 0) return `${h} h ${m} m`;
41	  return m > 0 ? `${m} m ${s} s` : `${s} s`;
42	};
43	
44	/** Valeur d'un mode continu, avec l'unité du mode — 2 décimales pour les grandeurs sous 10 (mm,
45	 * mm/mm...), sans décimale au-delà (mm/s, °C, %...) pour rester lisible. */
46	const formatColorByValue = (mode: ContinuousColorByMode, value: number) => {
47	  const digits = Math.abs(value) < 10 ? 2 : 0;
48	  return `${formatNumber(value, digits)} ${COLOR_BY_UNITS[mode]}`;
49	};
50	
51	// Même cascade d'apparition que GCodeSpeedSelector (fondu-montée, easing « standard » Material).
52	const containerVariants = {
53	  hidden: {},
54	  visible: { transition: { staggerChildren: 0.02 } },
55	};
56	const itemVariants = {
57	  hidden: { opacity: 0, y: 6 },
58	  visible: { opacity: 1, y: 0, transition: { duration: 0.22, ease: [0.4, 0, 0.2, 1] as const } },
59	};
60	
61	/** Groupes du sélecteur « colorer par » (cf. GCodeColorBySelector) : le type de ligne reste seul et
62	 * toujours en tête, les modes continus sont classés par famille pour rester lisibles malgré leur
63	 * nombre (~13, trop pour un simple bouton segmenté). */
64	const COLOR_BY_GROUPS: { label: string; modes: ContinuousColorByMode[] }[] = [
65	  { label: 'Cinématique', modes: ['speed', 'accel', 'headAngle', 'segmentLength', 'elapsedTime'] },
66	  { label: 'Extrusion', modes: ['volumetricFlow', 'extrusionRatio', 'lineWidth', 'layerHeight'] },
67	  { label: 'Vitesse relative', modes: ['layerSpeedRatio'] },
68	  { label: 'Thermique / refroidissement', modes: ['temperature', 'fanSpeed'] },
69	];
70	
71	const GRADIENT_CSS = `linear-gradient(90deg, ${COLORMAP_STOPS_HEX.join(', ')})`;
72	// Barre de la légende en mode continu : verticale (Min en bas, Max en haut — sens habituel d'une
73	// échelle thermique), donc la rampe est retournée par rapport à GRADIENT_CSS (horizontal, gauche à
74	// droite = bleu → rouge dans gcodeColormap.ts).
75	const VERTICAL_GRADIENT_CSS = `linear-gradient(0deg, ${COLORMAP_STOPS_HEX.join(', ')})`;
76	
77	/**
78	 * Sélecteur du critère de coloration du tracé : pas de bandeau séparé — le libellé « Type de ligne »
79	 * de l'en-tête de colonne EST le déclencheur (cadre au survol + chevron), et prend le nom du mode
80	 * actif quand ce n'est plus le type de ligne. Menu construit sur le même design que les menus de
81	 * catégorie de CategoriesSidebar (sectionGroup/sectionTitle/itemsList/itemRow, curseur de défilement
82	 * externe — cf. useExternalScrollThumb) : groupé, trop d'options (type de ligne + une douzaine de
83	 * modes continus) pour un bouton segmenté à plat.
84	 */
85	const GCodeColorBySelector: React.FC<{ colorBy: ColorByMode; setColorBy: (mode: ColorByMode) => void }> = ({
86	  colorBy,
87	  setColorBy,
88	}) => {
89	  const [open, setOpen] = React.useState(false);
90	  const contentRef = React.useRef<HTMLDivElement>(null);
91	  const { thumbHeight, thumbTop, hasScroll, isDragging, handleScroll, handleMouseDown } = useExternalScrollThumb(contentRef);
92	  const activeLabel = colorBy === 'lineType' ? 'Type de ligne' : COLOR_BY_LABELS[colorBy];
93	
94	  return (
95	    <Popover open={open} onOpenChange={setOpen}>
96	      <PopoverTrigger asChild>
97	        <button type="button" className={styles.colorByTrigger}>
98	          <span>{activeLabel}</span>
99	          <svg className={styles.colorByChevron} width="8" height="5" viewBox="0 0 8 5" fill="none" aria-hidden>
100	            <path d="M1 1L4 4L7 1" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
101	          </svg>
102	        </button>
103	      </PopoverTrigger>
104	      <PopoverContent
105	        className={styles.colorByMenu}
106	        align="start"
107	        sideOffset={6}
108	        collisionPadding={12}
109	        onMouseEnter={() => window.dispatchEvent(new CustomEvent('apex-reset-tooltip'))}
110	      >
111	        <div ref={contentRef} className={styles.colorByMenuContent} onScroll={handleScroll}>
112	          <ul className={styles.itemsList}>
113	            <li>
114	              <button
115	                type="button"
116	                className={clsx(styles.itemRow, styles.clickableRow, { [styles.activeItemRow]: colorBy === 'lineType' })}
117	                onClick={() => { setColorBy('lineType'); setOpen(false); }}
118	              >
119	                <span className={styles.itemName}>Type de ligne</span>
120	              </button>
121	            </li>
122	          </ul>
123	          {COLOR_BY_GROUPS.map((group) => (
124	            <div key={group.label} className={styles.sectionGroup}>
125	              <h4 className={styles.sectionTitle}>{group.label}</h4>
126	              <ul className={styles.itemsList}>
127	                {group.modes.map((mode) => (
128	                  <li key={mode}>
129	                    <button
130	                      type="button"
131	                      className={clsx(styles.itemRow, styles.clickableRow, { [styles.activeItemRow]: colorBy === mode })}
132	                      onClick={() => { setColorBy(mode); setOpen(false); }}
133	                    >
134	                      <span className={styles.itemName}>{COLOR_BY_LABELS[mode]}</span>
135	                      <span className={styles.colorByItemSwatch} style={{ background: GRADIENT_CSS }} aria-hidden />
136	                    </button>
137	                  </li>
138	                ))}
139	              </ul>
140	            </div>
141	          ))}
142	        </div>
143	        {hasScroll && (
144	          <div
145	            className={clsx(styles.externalScrollThumb, { [styles.dragging]: isDragging })}
146	            onMouseDown={handleMouseDown}
147	            style={{ height: `${thumbHeight}px`, top: `${thumbTop}px` }}
148	          />
149	        )}
150	      </PopoverContent>
151	    </Popover>
152	  );
153	};
154	
155	interface GCodeGradientScaleProps {
156	  mode: ContinuousColorByMode;
157	  /** Bornes réelles du fichier pour ce mode : limites que les poignées ne peuvent pas dépasser. */
158	  fileRange: ColorByRange;
159	  /** Portée actuellement affichée (curseurs + écrêtage), déjà résolue sur les bornes du fichier si
160	   * l'utilisateur n'y a jamais touché (cf. `activeColorByScope` dans use-gcode-preview.ts). */
161	  scope: ColorByScope;
162	  setScope: (mode: ContinuousColorByMode, scope: ColorByScope) => void;
163	  precisionBounds: { min: number; max: number };
164	  activePrecisionMm: number | null;
165	  setPrecision: (mode: ContinuousColorByMode, mm: number | null) => void;
166	}
167	
168	/** Fraction [0,1] de `value` dans `fileRange`, pour positionner une poignée le long de la barre. */
169	const fractionOf = (value: number, fileRange: ColorByRange) => {
170	  const span = fileRange.max - fileRange.min;
171	  return span > 1e-9 ? (value - fileRange.min) / span : 0.5;
172	};
173	
174	// Crans du curseur de portée : incrément de base 1 unité (1 mm/s, 1°C, 1%...) sur l'essentiel de la
175	// plage, qui se réduit d'un facteur 10 par dixième de plage restant en se rapprochant de la borne
176	// minimale du fichier (le « bord petit ») — permet un réglage fin de valeurs proches de zéro/du bas
177	// de l'échelle (ex. hauteur de couche en mm) sans perdre les crans grossiers, lisibles au glisser,
178	// sur le reste de la plage (jamais plus fin que l'unité de base au-delà du premier dixième). Effet
179	// recherché en second lieu : moins de valeurs distinctes possibles → moins de recalculs du tampon
180	// de couleurs par sommet pendant le glisser (cf. GCodeGradientScale), qui masque le lag observé en
181	// rendant le mouvement du curseur volontairement saccadé plutôt que trahir la latence d'un recalcul
182	// à chaque pixel.
183	const RANGE_HANDLE_BASE_STEP = 1;
184	const snapRangeValue = (value: number, fileRange: ColorByRange) => {
185	  const span = fileRange.max - fileRange.min;
186	  if (!(span > 1e-9)) return value;
187	  const distFromMin = value - fileRange.min;
188	  // Fraction de plage restant jusqu'au minimum (0 = collé au minimum, 1 = un dixième de plage
189	  // au-dessus ou plus) : le cran ne s'affine que dans ce premier dixième, jamais au-delà.
190	  const nearMin = Math.min(1, distFromMin / (span * 0.1));
191	  // nearMin = 0 → step = BASE_STEP / 10 (le plus fin, collé au minimum) ; nearMin = 1 → step =
192	  // BASE_STEP (le cran normal, dès qu'on s'éloigne d'un dixième de plage du minimum).
193	  const step = RANGE_HANDLE_BASE_STEP / Math.pow(10, 1 - nearMin);
194	  const snapped = fileRange.min + Math.round(distFromMin / step) * step;
195	  return Math.max(fileRange.min, Math.min(fileRange.max, snapped));
196	};
197	
198	/**
199	 * Barre de dégradé verticale + curseur double (min/max) + case « hors-portée en gris » : resserrer
200	 * les poignées RECADRE toute la rampe sur l'intervalle choisi (les valeurs qu'il contient s'étalent
201	 * sur tout le dégradé bleu→rouge), ce que la barre elle-même représente déjà en totalité — seules
202	 * les poignées se déplacent le long d'elle, positionnées par fraction des bornes RÉELLES du fichier
203	 * (`fileRange`), pour indiquer où se situe la portée choisie dans l'étendue complète des valeurs.
204	 */
205	const GCodeGradientScale: React.FC<GCodeGradientScaleProps> = ({
206	  mode, fileRange, scope, setScope, precisionBounds, activePrecisionMm, setPrecision,
207	}) => {
208	  const trackRef = React.useRef<HTMLDivElement>(null);
209	  const [dragging, setDragging] = React.useState<'min' | 'max' | null>(null);
210	
211	  // Poignées positionnées de BAS en HAUT (min en bas, max en haut — sens de VERTICAL_GRADIENT_CSS),
212	  // donc `bottom: fraction * 100%` plutôt que `top`.
213	  const minFraction = fractionOf(scope.min, fileRange);
214	  const maxFraction = fractionOf(scope.max, fileRange);
215	
216	  const setFromClientY = (clientY: number, handle: 'min' | 'max') => {
217	    const track = trackRef.current;
218	    if (!track) return;
219	    const rect = track.getBoundingClientRect();
220	    const fraction = rect.height > 0 ? 1 - Math.max(0, Math.min(1, (clientY - rect.top) / rect.height)) : 0;
221	    const value = snapRangeValue(fileRange.min + fraction * (fileRange.max - fileRange.min), fileRange);
222	    if (handle === 'min') {
223	      setScope(mode, { ...scope, min: Math.min(value, scope.max) });
224	    } else {
225	      setScope(mode, { ...scope, max: Math.max(value, scope.min) });
226	    }
227	  };
228	
229	  const startDrag = (handle: 'min' | 'max') => (e: React.PointerEvent) => {
230	    e.currentTarget.setPointerCapture(e.pointerId);
231	    setDragging(handle);
232	    setFromClientY(e.clientY, handle);
233	  };
234	
235	  return (
236	    <div className={styles.gradientScaleWrap}>
237	      <div className={styles.gradientScale}>
238	        <div ref={trackRef} className={styles.gradientBarTrack}>
239	          {/* Piste grise pleine hauteur en dessous, bande de dégradé RECADRÉE entre les deux
240	              poignées par-dessus : au-delà de la portée choisie, le tracé n'est plus coloré par
241	              cette partie de la rampe (gris ou écrêté selon la case, cf. gcodeColormap.ts) — la
242	              barre doit donc représenter la même chose, pas le dégradé complet en permanence. La
243	              bande étale le dégradé complet sur SA PROPRE hauteur (bleu au minimum choisi, rouge au
244	              maximum choisi), exactement comme les couleurs qu'affiche le tracé recadré. */}
245	          <div className={styles.gradientBarOut} />
246	          <div
247	            className={styles.gradientBar}
248	            style={{
249	              background: VERTICAL_GRADIENT_CSS,
250	              top: `${(1 - maxFraction) * 100}%`,
251	              bottom: `${minFraction * 100}%`,
252	            }}
253	          />
254	          <div
255	            className={clsx(styles.gradientHandle, { [styles.gradientHandleActive]: dragging === 'max' })}
256	            style={{ bottom: `${maxFraction * 100}%` }}
257	            onPointerDown={startDrag('max')}
258	            onPointerMove={(e) => dragging === 'max' && setFromClientY(e.clientY, 'max')}
259	            onPointerUp={() => setDragging(null)}
260	            role="slider"
261	            aria-label={`${COLOR_BY_LABELS[mode]} — borne maximale`}
262	            aria-valuemin={fileRange.min}
263	            aria-valuemax={fileRange.max}
264	            aria-valuenow={scope.max}
265	          />
266	          <div
267	            className={clsx(styles.gradientHandle, { [styles.gradientHandleActive]: dragging === 'min' })}
268	            style={{ bottom: `${minFraction * 100}%` }}
269	            onPointerDown={startDrag('min')}
270	            onPointerMove={(e) => dragging === 'min' && setFromClientY(e.clientY, 'min')}
271	            onPointerUp={() => setDragging(null)}
272	            role="slider"
273	            aria-label={`${COLOR_BY_LABELS[mode]} — borne minimale`}
274	            aria-valuemin={fileRange.min}
275	            aria-valuemax={fileRange.max}
276	            aria-valuenow={scope.min}
277	          />
278	        </div>
279	        {/* Ordre visuel Max → Moy. → Min, du haut vers le bas, aligné sur le sens de la barre
280	            (rouge/max en haut, bleu/min en bas). Moy. reste la vraie moyenne du FICHIER (jamais
281	            recalculée sur la portée resserrée) : atténuée si elle tombe hors de la portée choisie,
282	            pour signaler qu'elle n'est plus représentative de ce qui est actuellement affiché. */}
283	        <div className={styles.gradientStats}>
284	          <div className={styles.gradientStat}>
285	            <span className={styles.gradientStatLabel}>Max</span>
286	            <span className={styles.gradientStatValue}>{formatColorByValue(mode, scope.max)}</span>
287	          </div>
288	          <div className={clsx(styles.gradientStat, {
289	            [styles.gradientStatOutOfScope]: fileRange.avg < scope.min || fileRange.avg > scope.max,
290	          })}
291	          >
292	            <span className={styles.gradientStatLabel}>Moy.</span>
293	            <span className={styles.gradientStatValue}>{formatColorByValue(mode, fileRange.avg)}</span>
294	          </div>
295	          <div className={styles.gradientStat}>
296	            <span className={styles.gradientStatLabel}>Min</span>
297	            <span className={styles.gradientStatValue}>{formatColorByValue(mode, scope.min)}</span>
298	          </div>
299	        </div>
300	      </div>
301	      <label
302	        className={styles.grayOutOfScopeRow}
303	        onMouseEnter={() => window.dispatchEvent(new CustomEvent('apex-set-tooltip', {
304	          detail: {
305	            title: 'Hors-portée en gris',
306	            desc: 'Coché : les trajectoires en dehors de la portée choisie sont grisées. Décoché : elles prennent la couleur la plus proche de la rampe (bleu en dessous du minimum, rouge au-dessus du maximum).',
307	          },
308	        }))}
309	        onMouseLeave={() => window.dispatchEvent(new CustomEvent('apex-reset-tooltip'))}
310	      >
311	        <input
312	          type="checkbox"
313	          className={styles.checkbox}
314	          checked={scope.grayOutOfScope}
315	          onChange={(e) => setScope(mode, { ...scope, grayOutOfScope: e.target.checked })}
316	        />
317	        <span>Hors-portée en gris</span>
318	      </label>
319	      <GCodeRenderPrecisionSlider
320	        mode={mode}
321	        bounds={precisionBounds}
322	        activeMm={activePrecisionMm}
323	        setPrecision={setPrecision}
324	      />
325	    </div>
326	  );
327	};
328	
329	/**
330	 * Curseur « Précision du rendu » : longueur maximale (mm) d'un sous-segment cartésien avant d'être
331	 * encore subdivisé (cf. createSampler dans gcodeLayer.ts) — plus la valeur est petite, plus la
332	 * couleur peut changer finement le long d'un même mouvement, ce qui corrige l'effet de moiré visible
333	 * sur de longs traits quand un seul point de couleur existe par mouvement. Maximum = comportement
334	 * actuel (un anneau par mouvement, pas de subdivision, `activeMm = null`) ; minimum = 20× plus fin.
335	 * Reconstruit la géométrie des cordons (cf. gcodeLayer.ts setRenderPrecision) : volontairement
336	 * appliqué seulement au RELÂCHEMENT du curseur, jamais pendant le glisser (trop coûteux à répéter à
337	 * chaque pixel) — un état local suit le glisser pour l'affichage de la valeur, sans reconstruire.
338	 */
339	const GCodeRenderPrecisionSlider: React.FC<{
340	  mode: ContinuousColorByMode;
341	  bounds: { min: number; max: number };
342	  activeMm: number | null;
343	  setPrecision: (mode: ContinuousColorByMode, mm: number | null) => void;
344	}> = ({ mode, bounds, activeMm, setPrecision }) => {
345	  // null (comportement par défaut, pas encore réglé) affiché au maximum du curseur (le moins
346	  // précis) — cohérent avec `activeMm == null ⇔ comportement actuel` côté calque.
347	  const [localMm, setLocalMm] = React.useState(activeMm ?? bounds.max);
348	  React.useEffect(() => setLocalMm(activeMm ?? bounds.max), [activeMm, bounds.max]);
349	
350	  const ratio = bounds.max > bounds.min ? (localMm - bounds.min) / (bounds.max - bounds.min) : 1;
351	
352	  const commit = (mm: number) => {
353	    // Collé au maximum : redevient `null` (comportement par défaut), pas une valeur explicite égale
354	    // au maximum — évite une reconstruction inutile si l'utilisateur ramène juste le curseur au bout.
355	    setPrecision(mode, mm >= bounds.max - 1e-9 ? null : mm);
356	  };
357	
358	  const setFromClientX = (clientX: number, track: HTMLDivElement) => {
359	    const rect = track.getBoundingClientRect();
360	    const localRatio = rect.width > 0 ? Math.max(0, Math.min(1, (clientX - rect.left) / rect.width)) : 1;
361	    setLocalMm(bounds.min + localRatio * (bounds.max - bounds.min));
362	  };
363	
364	  return (
365	    <div
366	      className={styles.precisionRow}
367	      onMouseEnter={() => window.dispatchEvent(new CustomEvent('apex-set-tooltip', {
368	        detail: {
369	          title: 'Précision du rendu',
370	          desc: "Subdivise les mouvements pour que la couleur puisse changer plus finement le long du tracé — réduit l'effet de bandes visible sur les longs traits, au prix d'une géométrie plus lourde.",
371	        },
372	      }))}
373	      onMouseLeave={() => window.dispatchEvent(new CustomEvent('apex-reset-tooltip'))}
374	    >
375	      <div className={styles.precisionLabelRow}>
376	        <span className={styles.precisionLabel}>Précision du rendu</span>
377	        <span className={styles.precisionValue}>{formatNumber(localMm, localMm < 1 ? 3 : 2)} mm</span>
378	      </div>
379	      <div
380	        className={styles.precisionTrack}
381	        onPointerDown={(e) => {
382	          e.currentTarget.setPointerCapture(e.pointerId);
383	          setFromClientX(e.clientX, e.currentTarget);
384	        }}
385	        onPointerMove={(e) => { if (e.buttons === 1) setFromClientX(e.clientX, e.currentTarget); }}
386	        onPointerUp={() => commit(localMm)}
387	        role="slider"
388	        aria-label="Précision du rendu"
389	        aria-valuemin={bounds.min}
390	        aria-valuemax={bounds.max}
391	        aria-valuenow={localMm}
392	      >
393	        <div className={styles.precisionTrackFill} style={{ width: `${ratio * 100}%` }} />
394	        <div className={styles.precisionHandle} style={{ left: `${ratio * 100}%` }} />
395	      </div>
396	    </div>
397	  );
398	};
399	
400	/**
401	 * Légende de l'espace Prévisualisation, posée dans le panneau du haut de CategoriesSidebar : le
402	 * sélecteur « colorer par » en en-tête, puis le corps de la légende selon le mode actif —
403	 * couleur/durée/pourcentage/longueur/poids par type de ligne (défaut), ou dégradé + min/moyenne/max
404	 * pour un mode continu (cf. gcodeColormap.ts).
405	 */
406	export const GCodeLineTypeLegend = React.memo<GCodeLineTypeLegendProps>(({
407	  fileInfo, visibility, onToggle, colorBy, setColorBy, activeColorByScope, setColorByScope,
408	  renderPrecisionBounds, activeRenderPrecisionMm, setRenderPrecision,
409	}) => {
410	  const totalTime = fileInfo?.totalTime ?? 0;
411	  const continuousMode = colorBy !== 'lineType' ? colorBy : null;
412	  const fileRange = continuousMode && fileInfo ? fileInfo.colorByRanges[continuousMode] : null;
413	
414	  return (
415	    <motion.div className={styles.root} variants={containerVariants} initial="hidden" animate="visible">
416	      {!continuousMode ? (
417	        <>
418	          <motion.div className={clsx(styles.grid, styles.header)} variants={itemVariants}>
419	            <GCodeColorBySelector colorBy={colorBy} setColorBy={setColorBy} />
420	            <span className={styles.numeric}>Durée</span>
421	            <span className={styles.numeric}>Pourcentage</span>
422	            <span className={styles.numeric}>Longueur</span>
423	            <span className={styles.numeric}>Poids</span>
424	            <span />
425	          </motion.div>
426	
427	          {fileInfo ? (
428	            <div className={styles.rows}>
429	              {LINE_TYPES.map((type) => {
430	                const stat = fileInfo.lineStats[type.id];
431	                const hasTime = !!stat && stat.time > 0;
432	                const hasFilament = type.kind === 'extrusion' && !!stat && stat.filamentMm > 0;
433	                const visible = visibility[type.id];
434	                return (
435	                  <motion.label
436	                    key={type.id}
437	                    className={clsx(styles.grid, styles.row, { [styles.off]: !visible })}
438	                    variants={itemVariants}
439	                    onMouseEnter={() => window.dispatchEvent(new CustomEvent('apex-set-tooltip', {
440	                      detail: { title: type.label, desc: type.description },
441	                    }))}
442	                    onMouseLeave={() => window.dispatchEvent(new CustomEvent('apex-reset-tooltip'))}
443	                  >
444	                    <span className={styles.name}>
445	                      <span className={styles.swatch} style={{ backgroundColor: type.color }} />
446	                      <span className={styles.label}>{type.label}</span>
447	                    </span>
448	                    <span className={clsx(styles.numeric, { [styles.dash]: !hasTime })}>
449	                      {hasTime ? formatDuration(stat.time) : DASH}
450	                    </span>
451	                    <span className={clsx(styles.numeric, { [styles.dash]: !hasTime })}>
452	                      {hasTime && totalTime > 0 ? `${formatNumber((stat.time / totalTime) * 100, 1)}%` : DASH}
453	                    </span>
454	                    <span className={clsx(styles.numeric, { [styles.dash]: !hasFilament })}>
455	                      {hasFilament ? `${formatNumber(stat.filamentMm / 1000, 2)} m` : DASH}
456	                    </span>
457	                    <span className={clsx(styles.numeric, { [styles.dash]: !hasFilament })}>
458	                      {hasFilament ? `${formatNumber(stat.massG, 2)} g` : DASH}
459	                    </span>
460	                    <input
461	                      type="checkbox"
462	                      className={styles.checkbox}
463	                      checked={visible}
464	                      onChange={(e) => onToggle(type.id, e.target.checked)}
465	                      aria-label={`Afficher : ${type.label}`}
466	                    />
467	                  </motion.label>
468	                );
469	              })}
470	            </div>
471	          ) : (
472	            <motion.p className={styles.gradientEmpty} variants={itemVariants}>
473	              Aucun G-code chargé.
474	            </motion.p>
475	          )}
476	        </>
477	      ) : (
478	        <motion.div className={styles.gradientPanel} variants={itemVariants}>
479	          <div className={clsx(styles.grid, styles.header)}>
480	            <GCodeColorBySelector colorBy={colorBy} setColorBy={setColorBy} />
481	          </div>
482	          {fileRange && activeColorByScope && renderPrecisionBounds ? (
483	            <GCodeGradientScale
484	              mode={continuousMode}
485	              fileRange={fileRange}
486	              scope={activeColorByScope}
487	              setScope={setColorByScope}
488	              precisionBounds={renderPrecisionBounds}
489	              activePrecisionMm={activeRenderPrecisionMm}
490	              setPrecision={setRenderPrecision}
491	            />
492	          ) : (
493	            <p className={styles.gradientEmpty}>Aucun G-code chargé.</p>
494	          )}
495	        </motion.div>
496	      )}
497	    </motion.div>
498	  );
499	});
500	GCodeLineTypeLegend.displayName = 'GCodeLineTypeLegend';
501

