1	import React, { useCallback, useLayoutEffect, useRef } from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import { Play, Pause } from 'lucide-react';
4	import { type GCodeFileInfo } from '@/hooks/use-gcode-preview';
5	import styles from './GCodePreviewBar.module.scss';
6	
7	interface GCodePreviewBarProps {
8	  /** Espace Prévisualisation affiché. Nécessaire mais pas suffisant pour afficher la barre : elle
9	   * reste en plus masquée tant qu'aucun G-code n'est chargé ni en cours de chargement (cf.
10	   * `fileInfo`/`isLoading`). */
11	  active: boolean;
12	  fileInfo: GCodeFileInfo | null;
13	  isLoading: boolean;
14	  t: number;
15	  lastIndex: number;
16	  isPlaying: boolean;
17	  togglePlay: () => void;
18	  seek: (value: number) => void;
19	  speed: number;
20	  setSpeed: (speed: number) => void;
21	  openFilePicker: () => void;
22	}
23	
24	// `active` (isPreviewActive) devient vrai dans `onCovered` (cf. Sidebar.tsx), à l'instant précis
25	// où le rideau plein écran (SpaceTransitionOverlay) vient de finir de se peindre — PAS quand il a
26	// fini de se lever. À ce même instant démarrent aussi, tous masqués par le rideau : la mitose
27	// pilule → panneaux de CategoriesSidebar (PREVIEW_MORPH_MS = 1370ms) et le déplacement de la barre
28	// d'aide TopRightMenu (RESHAPE_DURATION = 1100ms) — les deux plus longues animations de la
29	// séquence. Le rideau lui-même reste peint (phase "text") 1000ms puis met 575ms à se lever
30	// (phase "fadeout", cf. getTextMs/FADEOUT_MS) : il ne révèle donc la scène qu'à 1575ms après
31	// `onCovered`, quand tout le reste est déjà terminé. Pour que cette barre apparaisse EN DERNIER
32	// dans la séquence perçue (au lieu d'être déjà là, toute faite, dès que le rideau se lève comme
33	// tout le reste), son glissement-fondu ne démarre qu'une fois le rideau entièrement levé.
34	const CURTAIN_REVEAL_MS = 1575;
35	
36	/** Positions CSS du segment parcouru, du segment restant et de la poignée pour un ratio 0–1. */
37	const trackStyles = (ratio: number) => ({
38	  fillRight: `calc(${100 - ratio * 100}% + var(--handle-gap))`,
39	  remainderLeft: `calc(${ratio * 100}% + var(--handle-gap))`,
40	  handleLeft: `${ratio * 100}%`,
41	});
42	
43	/**
44	 * Barre de lecture de l'espace Prévisualisation : play/pause, curseur de progression, vitesse,
45	 * affichage des trajets à vide et import de fichier. Toute la logique vient de
46	 * `useGCodePreview` (voir Index.tsx, qui possède le hook et transmet ses props ici).
47	 *
48	 * Pour l'instant seuls le bouton Play/Pause et le curseur de progression sont branchés ; le reste
49	 * des props (vitesse, trajets à vide, import) restent transmises sans être encore affichées, pour
50	 * ne pas avoir à retoucher Index.tsx quand ce contenu sera ajouté.
51	 *
52	 * N'apparaît que si un G-code est chargé ou en cours de chargement (`fileInfo`/`isLoading`) — pas
53	 * seulement parce que l'espace Prévisualisation est affiché : sans trajectoire à montrer, la barre
54	 * de lecture n'a rien à piloter et reste masquée comme le reste du contenu ci-dessus.
55	 *
56	 * Glissement-fondu depuis le bas de l'écran à l'entrée dans l'espace, et inverse à la sortie —
57	 * comme le panneau du bas de CategoriesSidebar (cf. FROM_PREVIEW_FADE_MS), mais vertical plutôt
58	 * qu'horizontal puisque cette barre vient du bord bas de l'écran plutôt que du bord gauche.
59	 * Retardée (CURTAIN_REVEAL_MS) pour apparaître en tout dernier, une fois le rideau levé et le
60	 * reste de la séquence terminé — jamais à la sortie de l'espace, où elle disparaît normalement.
61	 * Cette même transition sert aussi à l'apparition/disparition au chargement/déchargement d'un
62	 * G-code une fois l'espace déjà affiché, sans le délai CURTAIN_REVEAL_MS (non pertinent hors de
63	 * la séquence d'entrée dans l'espace, cf. `visible` ci-dessous).
64	 */
65	export const GCodePreviewBar: React.FC<GCodePreviewBarProps> = ({
66	  active,
67	  fileInfo,
68	  isLoading,
69	  t,
70	  lastIndex,
71	  isPlaying,
72	  togglePlay,
73	  seek,
74	}) => {
75	  const trackRef = useRef<HTMLDivElement>(null);
76	  const visible = active && (!!fileInfo || isLoading);
77	
78	  // CURTAIN_REVEAL_MS ne doit retarder que la toute première apparition de la barre après l'entrée
79	  // dans l'espace (rideau qui se lève) — pas une réapparition ultérieure au chargement d'un
80	  // G-code alors que l'espace est déjà affiché depuis longtemps, qui doit être immédiate.
81	  const revealDelayMs = useRef(CURTAIN_REVEAL_MS);
82	  useLayoutEffect(() => {
83	    if (!active) revealDelayMs.current = CURTAIN_REVEAL_MS;
84	  }, [active]);
85	  const delay = revealDelayMs.current;
86	  if (visible) revealDelayMs.current = 0;
87	  // Pas de mouvement chargé : curseur figé au tout début plutôt que masqué, la barre reste posée.
