1	import React, { useRef, useState } from 'react';
2	import { motion } from 'framer-motion';
3	import clsx from 'clsx';
4	import { GCODE_SPEED_OPTIONS } from '@/hooks/use-gcode-preview';
5	import styles from './GCodeSpeedSelector.module.scss';
6	
7	interface GCodeSpeedSelectorProps {
8	  /** Multiplicateur du temps machine réel (cf. GCODE_SPEED_OPTIONS). */
9	  speed: number;
10	  setSpeed: (speed: number) => void;
11	  /** Tête d'outil complète (glTF entier) ou tronquée à la buse (cf. apex-gcode-show-full-head). */
12	  showFullHead: boolean;
13	  setShowFullHead: (show: boolean) => void;
14	}
15	
16	const TOOLTIP = {
17	  title: "Vitesse d'impression",
18	  desc: 'Vitesse de lecture de la prévisualisation, en multiple de la vitesse réelle de la machine (avances F du G-code).',
19	};
20	
21	const HEAD_TOOLTIP = {
22	  title: "Tête d'outil complète",
23	  desc: "Décochez pour ne plus afficher que la buse, en masquant le reste de la tête d'outil.",
24	};
25	
26	// Curseur en échelle logarithmique entre le plus petit et le plus grand préréglage : chaque
27	// préréglage (×4 du précédent) est ainsi à intervalle régulier sur la piste, et les faibles
28	// vitesses restent précises.
29	const MIN_SPEED = GCODE_SPEED_OPTIONS[0];
30	const MAX_SPEED = GCODE_SPEED_OPTIONS[GCODE_SPEED_OPTIONS.length - 1];
31	const LOG_RANGE = Math.log(MAX_SPEED / MIN_SPEED);
32	const speedToRatio = (speed: number) => Math.log(speed / MIN_SPEED) / LOG_RANGE;
33	const ratioToSpeed = (ratio: number) => MIN_SPEED * Math.exp(ratio * LOG_RANGE);
34	
35	const formatSpeed = (speed: number) => {
36	  if (speed < 1) return `${speed.toFixed(2)}×`;
37	  if (speed < 10) return `${speed.toFixed(1)}×`;
38	  return `${Math.round(speed)}×`;
39	};
40	
41	// Apparition à l'entrée dans l'espace Prévisualisation : jamais d'un coup avec le panneau qui le
42	// porte (cf. previewPanelFooter dans CategoriesSidebar.module.scss, qui ne fait qu'apparaître avec
43	// lui) — case puis curseur+préréglages, l'un après l'autre en cascade, même vocabulaire que la
44	// cascade de contenu de ModelingSidebar (CONTENT_STAGGER_MS/contentGroupVariants) : fondu-montée,
45	// easing "standard" Material.
46	const REVEAL_STAGGER_S = 0.09;
47	const REVEAL_ITEM_DURATION_S = 0.22;
48	const revealContainerVariants = {
49	  hidden: { transition: { staggerChildren: REVEAL_STAGGER_S } },
50	  visible: { transition: { staggerChildren: REVEAL_STAGGER_S } },
51	};
52	const revealItemVariants = {
53	  hidden: { opacity: 0, y: 6 },
54	  visible: { opacity: 1, y: 0, transition: { duration: REVEAL_ITEM_DURATION_S, ease: [0.4, 0, 0.2, 1] as const } },
55	};
56	// Décalage jusqu'à ce que .sliderGroup (second groupe de la cascade, cf. staggerChildren
57	// ci-dessus) ait lui-même fini d'apparaître : les trois phases du curseur (cf. plus bas) doivent
58	// se jouer une fois ce groupe pleinement visible, jamais en même temps que son propre fondu-montée
59	// — sinon la ligne s'estomperait en même temps que son conteneur encore transparent, terminant
60	// avant même que celui-ci ait fini d'apparaître.
61	const SLIDER_GROUP_REVEAL_S = REVEAL_STAGGER_S + REVEAL_ITEM_DURATION_S;
62	
63	// Le curseur se joue en TROIS temps distincts, jamais tous à la vitesse du fondu-montée du reste
64	// de la cascade (revealItemVariants) : (1) la ligne (trackFill/trackRemainder) apparaît d'abord
65	// SEULE, déjà à son minimum, sans la poignée ; (2) la poignée apparaît ensuite par-dessus, en la
66	// « coupant » (elle n'existe pas avant cet instant — jamais un fondu, jamais présente ni
67	// transparente pendant la phase 1, sans quoi elle se contenterait de s'éclaircir sur place au lieu
68	// de sembler couper la ligne) ; (3) le tout glisse alors, ensemble, du minimum jusqu'à la valeur
69	// réelle, sur une courbe expo-out — même famille que le glissement des panneaux/barres depuis le
70	// bord de l'écran (GCodePreviewBar, [0.16, 1, 0.3, 1]).
71	const SLIDER_LINE_APPEAR_S = 0.18;
72	const SLIDER_HANDLE_APPEAR_S = 0.15;
73	// La poignée apparaît une fois la ligne posée, la glissade démarrant juste après elle (cf. les
74	// `delay` ci-dessous, dérivés de ces deux constantes plutôt que répétés en dur) — le tout décalé
75	// après l'apparition de .sliderGroup lui-même (SLIDER_GROUP_REVEAL_S).
76	const SLIDER_LINE_DELAY_S = SLIDER_GROUP_REVEAL_S;
77	const SLIDER_HANDLE_DELAY_S = SLIDER_LINE_DELAY_S + SLIDER_LINE_APPEAR_S;
78	const SLIDER_GLIDE_DELAY_S = SLIDER_HANDLE_DELAY_S + SLIDER_HANDLE_APPEAR_S;
79	const SLIDER_GLIDE_S = 0.5;
80	const SLIDER_GLIDE_EASE = [0.16, 1, 0.3, 1] as const;
81	
82	/**
83	 * Sélecteur de vitesse de lecture de l'espace Prévisualisation, posé au bas du panneau du bas de
84	 * CategoriesSidebar (cf. `previewLowerContent`) : curseur continu, puis contrôle segmenté sur
85	 * GCODE_SPEED_OPTIONS juste en dessous.
86	 */
87	export const GCodeSpeedSelector: React.FC<GCodeSpeedSelectorProps> = ({
88	  speed,
89	  setSpeed,
90	  showFullHead,
91	  setShowFullHead,
92	}) => {
93	  const trackRef = useRef<HTMLDivElement>(null);
94	  const ratio = Math.min(1, Math.max(0, speedToRatio(speed)));
95	  // framer-motion applique `transition` à CHAQUE changement de cible, pas seulement au montage :
96	  // sans ce drapeau, un clic ou un glisser rejouait délai + glissade de l'intro (~1 s de retard).
97	  // Une fois l'intro terminée, la poignée suit la valeur instantanément.
98	  const [introDone, setIntroDone] = useState(false);
99	  const follow = { duration: 0 };
100	
101	  const setFromClientX = (clientX: number) => {
102	    const track = trackRef.current;
103	    if (!track) return;
104	    const rect = track.getBoundingClientRect();
105	    const localRatio = rect.width > 0 ? Math.min(1, Math.max(0, (clientX - rect.left) / rect.width)) : 0;
106	    // Aimanté sur les préréglages à proximité, pour pouvoir y revenir exactement au curseur.
107	    const snapped = GCODE_SPEED_OPTIONS.find((option) => Math.abs(speedToRatio(option) - localRatio) < 0.02);
108	    setSpeed(snapped ?? ratioToSpeed(localRatio));
109	  };
110	
111	  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
112	    const step = e.key === 'ArrowRight' || e.key === 'ArrowUp' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowDown' ? -1 : 0;
113	    if (!step) return;
114	    e.preventDefault();
115	    setSpeed(ratioToSpeed(Math.min(1, Math.max(0, ratio + step * 0.025))));
116	  };
117	
118	  return (
119	    <motion.div
120	      className={styles.root}
121	      variants={revealContainerVariants}
122	      initial="hidden"
123	      animate="visible"
124	    >
125	      <motion.label
126	        className={styles.checkboxRow}
127	        variants={revealItemVariants}
128	        onMouseEnter={() => window.dispatchEvent(new CustomEvent('apex-set-tooltip', { detail: HEAD_TOOLTIP }))}
129	        onMouseLeave={() => window.dispatchEvent(new CustomEvent('apex-reset-tooltip'))}
130	      >
131	        <input
132	          type="checkbox"
133	          className={styles.checkbox}
134	          checked={showFullHead}
135	          onChange={(e) => setShowFullHead(e.target.checked)}
136	        />
137	        <span>Afficher la tête d'outil complète</span>
138	      </motion.label>
139	
140	      <motion.div className={styles.sliderGroup} variants={revealItemVariants}>
141	        <div
142	          className={styles.sliderRow}
143	          onMouseEnter={() => window.dispatchEvent(new CustomEvent('apex-set-tooltip', { detail: TOOLTIP }))}
144	          onMouseLeave={() => window.dispatchEvent(new CustomEvent('apex-reset-tooltip'))}
145	        >
146	          <span className={styles.label}>Vitesse</span>
147	          <div
148	            ref={trackRef}
149	            className={styles.track}
150	            onPointerDown={(e) => {
151	              e.currentTarget.setPointerCapture(e.pointerId);
152	              setFromClientX(e.clientX);
153	            }}
154	            onPointerMove={(e) => {
155	              if (e.buttons === 1) setFromClientX(e.clientX);
156	            }}
157	            onKeyDown={handleKeyDown}
158	            tabIndex={0}
159	            role="slider"
160	            aria-label="Vitesse d'impression"
161	            aria-valuemin={MIN_SPEED}
162	            aria-valuemax={MAX_SPEED}
163	            aria-valuenow={speed}
164	            aria-valuetext={formatSpeed(speed)}
165	          >
166	            {/* Animation de MONTAGE seule (`initial` figé, jamais réévalué) : `ratio` ne change plus
167	                ensuite la forme de cette transition, seulement sa valeur cible (cf. `animate`),
168	                donc une interaction normale (drag, préréglage) suit 1:1 sans rejouer les trois
169	                phases. Phase 1, ligne seule à son minimum (right/left à la position `ratio = 0`) :
170	                un simple fondu, jamais de mouvement (elle EST déjà à sa position de départ).
171	                Phase 3 (glissade), retardée à SLIDER_GLIDE_DELAY_S : mouvement seul, plus de fondu
172	                (déjà pleinement opaque depuis la phase 1). */}
173	            <motion.div
174	              className={styles.trackFill}
175	              initial={{ opacity: 0, right: `calc(100% + var(--handle-gap))` }}
176	              animate={{
177	                opacity: 1,
178	                right: `calc(${100 - ratio * 100}% + var(--handle-gap))`,
179	              }}
180	              transition={introDone ? follow : {
181	                opacity: { duration: SLIDER_LINE_APPEAR_S, delay: SLIDER_LINE_DELAY_S },
182	                right: { duration: SLIDER_GLIDE_S, delay: SLIDER_GLIDE_DELAY_S, ease: SLIDER_GLIDE_EASE },
183	              }}
184	            />
185	            <motion.div
186	              className={styles.trackRemainder}
187	              initial={{ opacity: 0, left: 'var(--handle-gap)' }}
188	              animate={{
189	                opacity: 1,
190	                left: `calc(${ratio * 100}% + var(--handle-gap))`,
191	              }}
192	              transition={introDone ? follow : {
193	                opacity: { duration: SLIDER_LINE_APPEAR_S, delay: SLIDER_LINE_DELAY_S },
194	                left: { duration: SLIDER_GLIDE_S, delay: SLIDER_GLIDE_DELAY_S, ease: SLIDER_GLIDE_EASE },
195	              }}
196	            />
197	            {/* Phase 2, retardée à SLIDER_HANDLE_DELAY_S (une fois la ligne posée) : la poignée
198	                n'existe pas avant cet instant (opacité 0 jusque-là, jamais un fondu progressif
