3	import { Play, Download } from 'lucide-react';
4	import styles from './SliceSidebar.module.scss';
5	import { CustomTooltip } from './CustomTooltip';
6	
7	interface SliceSidebarProps {
8	  onSlice?: () => void;
9	  /** Espace Prévisualisation : le bouton exporte le G-code affiché au lieu de lancer le slicing. */
10	  previewExport?: {
11	    enabled: boolean;
12	    onExport: () => void;
13	    /** Pourquoi l'export est indisponible (tooltip). */
14	    reason: string;
15	  };
16	}
17	
18	export const SliceSidebar: React.FC<SliceSidebarProps> = ({ onSlice, previewExport }) => {
19	  const [hasModels, setHasModels] = useState(false);
20	
21	  useEffect(() => {
22	    const handleMeshSelected = (e: CustomEvent<{ name: string | null }>) => {
23	      if (e.detail?.name) {
24	        setHasModels(true);
25	      } else {
26	        setHasModels(false);
27	      }
28	    };
29	
30	    const handleMeshDeleted = (e: CustomEvent<{ name?: string }>) => {
31	      // If needed we can track remaining meshes, but for now if mesh deleted or plate cleared
32	      if (!e.detail?.name) {
33	        setHasModels(false);
34	      }
35	    };
36	
37	    const handleImportModel = () => {
38	      setHasModels(true);
39	    };
40	
41	    window.addEventListener('apex-mesh-selected', handleMeshSelected as EventListener);
42	    window.addEventListener('apex-mesh-deleted', handleMeshDeleted as EventListener);
43	    window.addEventListener('apex-import-model', handleImportModel as EventListener);
44	
45	    return () => {
46	      window.removeEventListener('apex-mesh-selected', handleMeshSelected as EventListener);
47	      window.removeEventListener('apex-mesh-deleted', handleMeshDeleted as EventListener);
48	      window.removeEventListener('apex-import-model', handleImportModel as EventListener);
49	    };
50	  }, []);
51	
52	  if (previewExport) {
53	    const { enabled, onExport, reason } = previewExport;
54	    return (
55	      <div className={styles.container} data-apex-chrome-panel>
56	        <div className={styles.toolbar}>
