1	import React, { useEffect, useMemo, useRef, useState } from 'react';
2	import { AnimatePresence, motion } from 'framer-motion';
3	import { CircleCheck, CircleX, TriangleAlert, Loader2, X } from 'lucide-react';
4	import {
5	  removeNotification,
6	  setFrontNotification,
7	  subscribeToNotifications,
8	  type NotificationItem,
9	  type NotificationVariant,
10	} from '@/utils/notificationStore';
11	import styles from './NotificationStack.module.scss';
12	
13	const MAX_PEEK = 3; // carte de face + jusqu'à 3 cartes qui dépassent derrière
14	
15	// Décalage par carte en pile (cf. dessin de référence : coins haut/droit qui dépassent).
16	const PEEK_OFFSET_X = 10;
17	const PEEK_OFFSET_Y = -10;
18	const SCALE_STEP = 0.05;
19	const OPACITY_STEP = 0.18;
20	
21	// Course de sortie de la carte quittant le premier plan (molette) : au-delà du coin d'ancrage,
22	// vers le bas-droite — jamais un simple fondu sur place.
23	const EXIT_PUSH_X = 60;
24	const EXIT_PUSH_Y = 40;
25	
26	const SPRING = { type: 'spring', stiffness: 380, damping: 34 } as const;
27	
28	const VARIANT_ICONS: Record<NotificationVariant, React.ReactNode> = {
29	  success: <CircleCheck size={18} />,
30	  error: <CircleX size={18} />,
31	  warning: <TriangleAlert size={18} />,
32	  loading: <Loader2 size={18} className="animate-spin" />,
33	};
34	
35	export const NotificationStack: React.FC = () => {
36	  const [items, setItems] = useState<NotificationItem[]>([]);
37	  const [frontId, setFrontIdState] = useState<string | null>(null);
38	  // Carte en train de quitter le premier plan (déclenchée par la molette) : reçoit la course de
39	  // sortie bas-droite le temps de son animation, plutôt que la trajectoire générique de pile.
40	  const [leavingId, setLeavingId] = useState<string | null>(null);
41	  const wheelLockRef = useRef(false);
42	
43	  useEffect(() => subscribeToNotifications((its, front) => {
44	    setItems(its);
45	    setFrontIdState(front);
46	  }), []);
47	
48	  // Ordre d'affichage face → fond : la carte forcée au premier plan (molette ou notif récente)
49	  // en tête, puis le reste par ordre d'ancienneté décroissante.
50	  const orderedIds = useMemo(() => {
51	    if (items.length === 0) return [];
52	    const ids = items.map((n) => n.id);
53	    const resolvedFront = frontId && ids.includes(frontId) ? frontId : ids[ids.length - 1];
54	    const rest = ids.filter((id) => id !== resolvedFront).reverse();
55	    return [resolvedFront, ...rest];
56	  }, [items, frontId]);
57	
58	  const visibleIds = orderedIds.slice(0, MAX_PEEK + 1);
59	
60	  const handleWheel = (e: React.WheelEvent) => {
61	    if (orderedIds.length < 2) return;
62	    e.preventDefault();
63	    if (wheelLockRef.current) return;
64	    wheelLockRef.current = true;
65	    setTimeout(() => { wheelLockRef.current = false; }, 220);
66	    const delta = e.deltaY > 0 ? 1 : -1;
67	    const nextIdx = ((delta % orderedIds.length) + orderedIds.length) % orderedIds.length;
68	    setLeavingId(orderedIds[0]);
69	    setFrontNotification(orderedIds[nextIdx]);
70	  };
71	
72	  if (visibleIds.length === 0) return null;
73	
74	  return (
75	    <div className={styles.stack} onWheel={handleWheel}>
76	      <AnimatePresence mode="popLayout">
77	        {visibleIds.map((id, stackIndex) => {
78	          const item = items.find((n) => n.id === id);
79	          if (!item) return null;
80	          const isLeaving = id === leavingId;
81	          return (
82	            <motion.div
83	              key={id}
84	              className={styles.card}
85	              data-variant={item.variant}
86	              style={{ zIndex: isLeaving ? 101 : 100 - stackIndex }}
87	              initial={{ opacity: 0, y: 20, scale: 0.9 }}
88	              animate={isLeaving ? {
89	                x: EXIT_PUSH_X,
90	                y: EXIT_PUSH_Y,
91	                scale: 1 - SCALE_STEP,
92	                opacity: 0,
93	              } : {
94	                x: stackIndex * PEEK_OFFSET_X,
95	                y: stackIndex * PEEK_OFFSET_Y,
96	                scale: 1 - stackIndex * SCALE_STEP,
97	                opacity: Math.max(0.15, 1 - stackIndex * OPACITY_STEP),
98	              }}
99	              exit={{ opacity: 0, x: EXIT_PUSH_X, y: EXIT_PUSH_Y, scale: 0.85 }}
100	              transition={SPRING}
101	              onAnimationComplete={() => {
102	                if (isLeaving) setLeavingId(null);
103	              }}
104	            >
105	              {stackIndex === 0 && !isLeaving && (
106	                <>
107	                  <span className={styles.icon}>{VARIANT_ICONS[item.variant]}</span>
108	                  <span className={styles.message}>{item.message}</span>
109	                  <button
110	                    type="button"
111	                    className={styles.close}
112	                    aria-label="Fermer"
113	                    onClick={() => removeNotification(id)}
114	                  >
115	                    <X size={14} />
116	                  </button>
117	                </>
118	              )}
119	              {(stackIndex > 0 || isLeaving) && <div className={styles.peekFill} />}
120	            </motion.div>
121	          );
122	        })}
123	      </AnimatePresence>
124	    </div>
125	  );
126	};
127

