const clicked = await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const testBtn = buttons.find((b) => b.textContent?.includes('Test notifs'));
  if (testBtn) { testBtn.click(); return true; }
  return false;
});
console.log('Clicked test button:', clicked);

await new Promise((r) => setTimeout(r, 1000));
await page.screenshot({ path: 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/942926a2-c276-4eb2-b91f-90c959aec044/scratchpad/notif_stack.png' });

const stackHtml = await page.evaluate(() => {
  const stack = document.querySelector('[class*="_stack_"]');
  return stack ? stack.outerHTML.slice(0, 3000) : 'NOT FOUND';
});
