import puppeteer from 'puppeteer';

const browser = await puppeteer.launch({ headless: 'new', args: ['--window-size=1400,900'] });
const page = await browser.newPage();
await page.setViewport({ width: 1400, height: 900 });

await page.goto('http://localhost:8080/', { waitUntil: 'networkidle0', timeout: 30000 });
await new Promise((r) => setTimeout(r, 1500));

await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const testBtn = buttons.find((b) => b.textContent?.includes('Test notifs'));
  if (testBtn) testBtn.click();
});
await new Promise((r) => setTimeout(r, 1000));

const box = await page.evaluate(() => {
  const stack = document.querySelector('[class*="_stack_"]');
  const rect = stack.getBoundingClientRect();
  // Union of all card rects
  const cards = Array.from(stack.querySelectorAll('[class*="_card_"]'));
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  cards.forEach((c) => {
    const r = c.getBoundingClientRect();
    minX = Math.min(minX, r.left);
    minY = Math.min(minY, r.top);
    maxX = Math.max(maxX, r.right);
    maxY = Math.max(maxY, r.bottom);
  });
  return { minX, minY, maxX, maxY };
});
console.log('Bounding box of all cards:', box);

const pad = 20;
await page.screenshot({
  path: 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/942926a2-c276-4eb2-b91f-90c959aec044/scratchpad/notif_stack_zoom.png',
  clip: {
    x: Math.max(0, box.minX - pad),
    y: Math.max(0, box.minY - pad),
    width: (box.maxX - box.minX) + pad * 2,
    height: (box.maxY - box.minY) + pad * 2,
  },
});

await browser.close();

