import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { CircleCheck, CircleX, TriangleAlert, Loader2, X } from 'lucide-react';
import {
  removeNotification,
  setFrontNotification,
  subscribeToNotifications,
  type NotificationItem,
  type NotificationVariant,
} from '@/utils/notificationStore';
import styles from './NotificationStack.module.scss';

const MAX_PEEK = 3; // carte de face + jusqu'à 3 cartes qui dépassent derrière

// Décalage par carte en pile (cf. dessin de référence : coins haut/droit qui dépassent).
const PEEK_OFFSET_X = 10;
const PEEK_OFFSET_Y = -10;
const SCALE_STEP = 0.05;
const OPACITY_STEP = 0.18;

// Course de sortie de la carte quittant le premier plan (molette) : au-delà du coin d'ancrage,
// vers le bas-droite — jamais un simple fondu sur place.
const EXIT_PUSH_X = 60;
const EXIT_PUSH_Y = 40;

const SPRING = { type: 'spring', stiffness: 380, damping: 34 } as const;

const VARIANT_ICONS: Record<NotificationVariant, React.ReactNode> = {
  success: <CircleCheck size={18} />,
  error: <CircleX size={18} />,
  warning: <TriangleAlert size={18} />,
  loading: <Loader2 size={18} className="animate-spin" />,
};

export const NotificationStack: React.FC = () => {
  const [items, setItems] = useState<NotificationItem[]>([]);
  const [frontId, setFrontIdState] = useState<string | null>(null);
  // Carte en train de quitter le premier plan (déclenchée par la molette) : reçoit la course de
  // sortie bas-droite le temps de son animation, plutôt que la trajectoire générique de pile.
  const [leavingId, setLeavingId] = useState<string | null>(null);
  const wheelLockRef = useRef(false);

  useEffect(() => subscribeToNotifications((its, front) => {
    setItems(its);
    setFrontIdState(front);
  }), []);

  // Ordre d'affichage face → fond : la carte forcée au premier plan (molette ou notif récente)
  // en tête, puis le reste par ordre d'ancienneté décroissante.
  const orderedIds = useMemo(() => {
    if (items.length === 0) return [];
    const ids = items.map((n) => n.id);
    const resolvedFront = frontId && ids.includes(frontId) ? frontId : ids[ids.length - 1];
    const rest = ids.filter((id) => id !== resolvedFront).reverse();
    return [resolvedFront, ...rest];
  }, [items, frontId]);

  const visibleIds = orderedIds.slice(0, MAX_PEEK + 1);

  const handleWheel = (e: React.WheelEvent) => {
    if (orderedIds.length < 2) return;
    e.preventDefault();
    if (wheelLockRef.current) return;
    wheelLockRef.current = true;
    setTimeout(() => { wheelLockRef.current = false; }, 220);
    const delta = e.deltaY > 0 ? 1 : -1;
    const nextIdx = ((delta % orderedIds.length) + orderedIds.length) % orderedIds.length;
    setLeavingId(orderedIds[0]);
    setFrontNotification(orderedIds[nextIdx]);
  };

  if (visibleIds.length === 0) return null;

  return (
    <div className={styles.stack} onWheel={handleWheel}>
      <AnimatePresence mode="popLayout">
        {visibleIds.map((id, stackIndex) => {
          const item = items.find((n) => n.id === id);
          if (!item) return null;
          const isLeaving = id === leavingId;
          return (
            <motion.div
              key={id}
              className={styles.card}
              data-variant={item.variant}
              style={{ zIndex: isLeaving ? 101 : 100 - stackIndex }}
              initial={{ opacity: 0, y: 20, scale: 0.9 }}
              animate={isLeaving ? {
                x: EXIT_PUSH_X,
                y: EXIT_PUSH_Y,
                scale: 1 - SCALE_STEP,
                opacity: 0,
              } : {
                x: stackIndex * PEEK_OFFSET_X,
                y: stackIndex * PEEK_OFFSET_Y,
                scale: 1 - stackIndex * SCALE_STEP,
                opacity: Math.max(0.15, 1 - stackIndex * OPACITY_STEP),
              }}
              exit={{ opacity: 0, x: EXIT_PUSH_X, y: EXIT_PUSH_Y, scale: 0.85 }}
              transition={SPRING}
              onAnimationComplete={() => {
                if (isLeaving) setLeavingId(null);
              }}
            >
              {stackIndex === 0 && !isLeaving && (
                <>
                  <span className={styles.icon}>{VARIANT_ICONS[item.variant]}</span>
                  <span className={styles.message}>{item.message}</span>
                  <button
                    type="button"
                    className={styles.close}
                    aria-label="Fermer"
                    onClick={() => removeNotification(id)}
                  >
                    <X size={14} />
                  </button>
                </>
              )}
              {(stackIndex > 0 || isLeaving) && <div className={styles.peekFill} />}
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
};

