import puppeteer from 'puppeteer';

const browser = await puppeteer.launch({ headless: 'new', args: ['--window-size=1400,900'] });
const page = await browser.newPage();
await page.setViewport({ width: 1400, height: 900 });

await page.goto('http://localhost:8080/', { waitUntil: 'networkidle0', timeout: 30000 });
await new Promise((r) => setTimeout(r, 1500));

await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const testBtn = buttons.find((b) => b.textContent?.includes('Test notifs'));
  if (testBtn) testBtn.click();
});
await new Promise((r) => setTimeout(r, 500));

function frontMessage() {
  return document.querySelector('[class*="_message_"]')?.textContent;
}

async function wheel(page, deltaY) {
  await page.evaluate((dy) => {
    const stack = document.querySelector('[class*="_stack_"]');
    const card = stack.querySelector('[class*="_card_"]');
    const rect = card.getBoundingClientRect();
    stack.dispatchEvent(new WheelEvent('wheel', {
      deltaY: dy, bubbles: true, cancelable: true,
      clientX: rect.left + rect.width / 2, clientY: rect.top + rect.height / 2,
    }));
  }, deltaY);
  await new Promise((r) => setTimeout(r, 500));
}

const sequence = [];
sequence.push(await page.evaluate(frontMessage));
await wheel(page, 100); // forward 1
sequence.push(await page.evaluate(frontMessage));
await wheel(page, 100); // forward 2
sequence.push(await page.evaluate(frontMessage));
await wheel(page, -100); // back 1 -> should match forward1's state
sequence.push(await page.evaluate(frontMessage));
await wheel(page, -100); // back 2 -> should match original front
sequence.push(await page.evaluate(frontMessage));

console.log('Sequence (start, fwd1, fwd2, back1, back2):');
sequence.forEach((s, i) => console.log(i, '=>', s));

// Check reversibility
const ok = sequence[0] === sequence[4] && sequence[1] === sequence[3];
console.log('REVERSIBLE:', ok);

// Check that the card leaving front goes all the way to the back slot, not slot 1
const html = await page.evaluate(() => document.querySelector('[class*="_stack_"]').outerHTML);
console.log(html.slice(0, 2500));

await browser.close();

