import puppeteer from 'puppeteer';

const browser = await puppeteer.launch({ headless: 'new', args: ['--window-size=1400,900'] });
const page = await browser.newPage();
await page.setViewport({ width: 1400, height: 900 });
page.on('console', (msg) => { if (/wheel|passive/i.test(msg.text())) console.log('PAGE LOG:', msg.text()); });

await page.goto('http://localhost:8080/', { waitUntil: 'networkidle0', timeout: 30000 });
await new Promise((r) => setTimeout(r, 1500));

await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const testBtn = buttons.find((b) => b.textContent?.includes('Test notifs'));
  if (testBtn) testBtn.click();
});
await new Promise((r) => setTimeout(r, 500));

function frontMessage() {
  return document.querySelector('[class*="_message_"]')?.textContent;
}

async function wheelAt(page, deltaY, moveMouseFirst) {
  const rect = await page.evaluate(() => {
    const card = document.querySelector('[class*="_card_"]');
    const r = card.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  });
  if (moveMouseFirst) {
    await page.mouse.move(rect.x, rect.y);
  }
  await page.evaluate((dy, x, y) => {
    const el = document.elementFromPoint(x, y);
    el.dispatchEvent(new WheelEvent('wheel', { deltaY: dy, bubbles: true, cancelable: true, clientX: x, clientY: y }));
  }, deltaY, rect.x, rect.y);
  await new Promise((r) => setTimeout(r, 400));
}

// Simulate: repeated wheel events WITHOUT moving mouse between each (real trackpad/mouse wheel
// scenario) - this is what the user describes breaking.
console.log('--- Repeated wheel without remove/re-add mouse ---');
console.log('0:', await page.evaluate(frontMessage));
await wheelAt(page, 100, false);
console.log('1 (after wheel down):', await page.evaluate(frontMessage));
await wheelAt(page, -100, false);
console.log('2 (after wheel up):', await page.evaluate(frontMessage));
await wheelAt(page, -100, false);
console.log('3 (after wheel up again):', await page.evaluate(frontMessage));
await wheelAt(page, 100, false);
console.log('4 (after wheel down):', await page.evaluate(frontMessage));

await browser.close();

