useEffect(() => {
  const el = stackRef.current;
  if (!el) return;
  const onWheel = (e: WheelEvent) => {
    const currentIds = idsRef.current;
    if (currentIds.length < 2) return;
    e.preventDefault();
    e.stopPropagation();
    if (wheelLockRef.current) return;
    wheelLockRef.current = true;
    // Verrou court : couvre juste un "tick" de molette physique (plusieurs deltaY groupés par le
    // système pour un seul cran), pas toute la durée de la spring — sinon un scroll un peu rapide
    // se sent bloqué/en retard alors que l'animation, elle, a déjà largement le temps de suivre.
    setTimeout(() => { wheelLockRef.current = false; }, 90);
    const dir = e.deltaY > 0 ? 1 : -1;
    const nextIndex = ((frontIndexRef.current + dir) % currentIds.length + currentIds.length) % currentIds.length;
    setFrontNotification(currentIds[nextIndex]);
  };
  el.addEventListener('wheel', onWheel, { passive: false });
  return () => el.removeEventListener('wheel', onWheel);
}, []);

