  return {
    x: slot * PEEK_OFFSET_X,
    y: slot * PEEK_OFFSET_Y,
    scale: 1 - slot * SCALE_STEP,
    opacity: Math.max(0.55, 1 - slot * OPACITY_STEP),
  };
}

