import puppeteer from 'puppeteer';

const browser = await puppeteer.launch({ headless: 'new', args: ['--window-size=1400,900'] });
const page = await browser.newPage();
await page.setViewport({ width: 1400, height: 900 });

await page.goto('http://localhost:8080/', { waitUntil: 'networkidle0', timeout: 30000 });
await new Promise((r) => setTimeout(r, 1500));

await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const testBtn = buttons.find((b) => b.textContent?.includes('Test notifs'));
  if (testBtn) testBtn.click();
});
await new Promise((r) => setTimeout(r, 500));

// Get camera radius before
const radiusBefore = await page.evaluate(() => {
  return window.__debugCameraRadius ? window.__debugCameraRadius() : null;
});

const front = await page.$('[class*="_front_"]');
const box = await front.boundingBox();
await page.mouse.move(box.x + box.width/2, box.y + box.height/2);
await page.mouse.wheel({ deltaY: 300 }); // large scroll, would zoom a lot if leaking
await new Promise((r) => setTimeout(r, 500));
await page.mouse.wheel({ deltaY: 300 });
await new Promise((r) => setTimeout(r, 500));

// Screenshot the 3D scene area (top area away from notif stack) before/after to visually compare zoom
await page.screenshot({ path: 'C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/942926a2-c276-4eb2-b91f-90c959aec044/scratchpad/scene_after_wheel.png' });

const msg = await page.evaluate(() => document.querySelector('[class*="_front_"] [class*="_message_"]')?.textContent);
console.log('front message after 2 wheels of 300:', msg);

await browser.close();

