import puppeteer from 'puppeteer';

const browser = await puppeteer.launch({ headless: 'new', args: ['--window-size=1400,900'] });
const page = await browser.newPage();
await page.setViewport({ width: 1400, height: 900 });

await page.goto('http://localhost:8080/', { waitUntil: 'networkidle0', timeout: 30000 });
await new Promise((r) => setTimeout(r, 1500));

// Push 10 distinct notifications via the store directly (bypassing the x4 test button) to have
// enough items to observe several distinct steps of inertia.
await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const testBtn = buttons.find((b) => b.textContent?.includes('Test notifs'));
  if (testBtn) {
    for (let i = 0; i < 3; i++) testBtn.click();
  }
});
await new Promise((r) => setTimeout(r, 500));

function frontMessage() {
  return document.querySelector('[class*="_front_"] [class*="_message_"]')?.textContent;
}

const cardCount = await page.evaluate(() => document.querySelectorAll('[class*="_card_"]').length);
console.log('distinct cards visible (capped at MAX_PEEK+1):', cardCount);
const totalItems = await page.evaluate(() => {
  // count via React internals is hard; just trust 3 clicks x 4 = 12 pushes
  return 'n/a';
});

console.log('start:', await page.evaluate(frontMessage));

const front = await page.$('[class*="_front_"]');
const box = await front.boundingBox();
await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);

// Single large flick
await page.mouse.wheel({ deltaY: 400 });

// Sample the front message over time to observe multiple distinct steps happening after ONE flick
for (let i = 0; i < 10; i++) {
  await new Promise((r) => setTimeout(r, 100));
  const msg = await page.evaluate(frontMessage);
  console.log(`t=${(i + 1) * 100}ms:`, msg);
}

await browser.close();

