cd "C:/Users/test_/AppData/Local/Temp/claude/r--APEX-NEW-VERSION-slicer-ux/942926a2-c276-4eb2-b91f-90c959aec044/scratchpad" && cat > test_inertia_stop.mjs << 'EOF'
import puppeteer from 'puppeteer';

const browser = await puppeteer.launch({ headless: 'new', args: ['--window-size=1400,900'] });
const page = await browser.newPage();
await page.setViewport({ width: 1400, height: 900 });

await page.goto('http://localhost:8080/', { waitUntil: 'networkidle0', timeout: 30000 });
await new Promise((r) => setTimeout(r, 1500));
await page.evaluate(() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const testBtn = buttons.find((b) => b.textContent?.includes('Test notifs'));
  if (testBtn) for (let i = 0; i < 3; i++) testBtn.click();
});
await new Promise((r) => setTimeout(r, 500));

const front = await page.$('[class*="_front_"]');
const box = await front.boundingBox();
await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
await page.mouse.wheel({ deltaY: 400 });

await new Promise((r) => setTimeout(r, 2000)); // let inertia fully settle
const msg1 = await page.evaluate(() => document.querySelector('[class*="_front_"] [class*="_message_"]')?.textContent);
await new Promise((r) => setTimeout(r, 1000)); // wait more, should NOT keep moving
const msg2 = await page.evaluate(() => document.querySelector('[class*="_front_"] [class*="_message_"]')?.textContent);
console.log('after 2s:', msg1);
console.log('after 3s (should be same, stopped):', msg2);
console.log('STOPPED CORRECTLY:', msg1 === msg2);

// Also test reversibility still holds: go forward then back by wheel with small ticks
async function smallWheel(dy) {
  await page.evaluate((d) => {
    const stack = document.querySelector('[class*="_stack_"]');
    const card = stack.querySelector('[class*="_front_"]');
    const r = card.getBoundingClientRect();
    stack.dispatchEvent(new WheelEvent('wheel', { deltaY: d, bubbles: true, cancelable: true, clientX: r.left+10, clientY: r.top+10 }));
  }, dy);
  await new Promise((r) => setTimeout(r, 500)); // let any inertia from this tiny kick fully settle
}
const start = await page.evaluate(() => document.querySelector('[class*="_front_"] [class*="_message_"]')?.textContent);
await smallWheel(50);
const fwd = await page.evaluate(() => document.querySelector('[class*="_front_"] [class*="_message_"]')?.textContent);
await smallWheel(-50);
const back = await page.evaluate(() => document.querySelector('[class*="_front_"] [class*="_message_"]')?.textContent);
console.log('start:', start);
console.log('fwd:', fwd);
console.log('back (should == start):', back);
console.log('SMALL-TICK REVERSIBLE:', start === back);

await browser.close();
EOF
